describe('Table Row Highlighting', () => {
    beforeEach(() => {
        cy.visit('/table'); // Replace with the actual URL of the table
    });

    it('should highlight selected rows in a different colour', () => {
        cy.get('table tbody tr').first().click(); // Select the first row
        cy.get('table tbody tr.selected').should('have.css', 'background-color', 'rgb(255, 255, 0)'); // Assuming yellow highlight
    });

    it('should not highlight unselected rows', () => {
        cy.get('table tbody tr').first().click(); // Select the first row
        cy.get('table tbody tr').not('.selected').should('not.have.css', 'background-color', 'rgb(255, 255, 0)'); // Ensure other rows are not highlighted
    });
});
